120	func (h *handler) updateFeedHandler(w http.ResponseWriter, r *http.Request) {
121		feedID := request.RouteInt64Param(r, "feedID")
122		if feedID == 0 {
123			response.JSONBadRequest(w, r, errors.New("invalid feed ID"))
124			return
125		}
126	
127		var feedModificationRequest model.FeedModificationRequest
128		if err := json_parser.NewDecoder(r.Body).Decode(&feedModificationRequest); err != nil {
129			response.JSONBadRequest(w, r, err)
130			return
131		}
132	
133		userID := request.UserID(r)
134		originalFeed, err := h.store.FeedByID(userID, feedID)
135		if err != nil {
136			response.JSONServerError(w, r, err)
137			return
138		}
139	
140		if originalFeed == nil {
141			response.JSONNotFound(w, r)
142			return
143		}
144	
145		if validationErr := validator.ValidateFeedModification(h.store, userID, originalFeed.ID, &feedModificationRequest); validationErr != nil {
146			response.JSONBadRequest(w, r, validationErr.Error())
147			return
148		}
149	
150		feedModificationRequest.Patch(originalFeed)
151		originalFeed.ResetErrorCounter()
152		if err := h.store.UpdateFeed(originalFeed); err != nil {
153			response.JSONServerError(w, r, err)
154			return
155		}
156	
157		originalFeed, err = h.store.FeedByID(userID, feedID)
158		if err != nil {
159			response.JSONServerError(w, r, err)
160			return
161		}
162	
163		response.JSONCreated(w, r, originalFeed)
164	}
